define('tao/lockDownBrowser/lockDownBrowserEventBus',['core/eventifier'], function (eventifier) {
  'use strict';

  var exitMenuEnabled = false;
  return eventifier({
    enableExitMenu: function enableExitMenu() {
      exitMenuEnabled = true;
    },
    disableExitMenu: function disableExitMenu() {
      exitMenuEnabled = false;
    },
    isExitMenuEnabled: function isExitMenuEnabled() {
      return exitMenuEnabled;
    }
  });
});
